package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.*;
import com.fasterxml.jackson.databind.deser.impl.PropertyBasedCreator;
import com.fasterxml.jackson.databind.deser.impl.PropertyValueBuffer;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId.Referring;
import com.fasterxml.jackson.databind.deser.std.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.KeyDeserializer;
import com.fasterxml.jackson.databind.deser.std.MapDeserializer;
import com.fasterxml.jackson.databind.deser.std.TypeDeserializer;
import com.fasterxml.jackson.databind.deser.std.ValueInstantiator;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.math.*;
import java.util.*;
import java.util.HashSet;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;

public class MapDeserializer_isCachable_TriageGen0Test {

    @Test
    public void testIsCachable_BothNull_ReturnsTrue() {
        // Arrange: _valueTypeDeserializer is null and _ignorableProperties is null
        JavaType mapType = mock(JavaType.class);
        ValueInstantiator valueInstantiator = mock(ValueInstantiator.class);
        KeyDeserializer keyDeser = null;
        JsonDeserializer<Object> valueDeser = null;
        TypeDeserializer valueTypeDeser = null; // This is null

        MapDeserializer deserializer = new MapDeserializer(mapType, valueInstantiator, keyDeser, valueDeser, valueTypeDeser);

        // Act & Assert
        assertTrue("Should be cachable when both deserializer and ignorable properties are null", 
            deserializer.isCachable());
    }

    @Test
    public void testIsCachable_ValueTypeDeserializerNotNull_ReturnsFalse() {
        // Arrange: _valueTypeDeserializer is NOT null
        JavaType mapType = mock(JavaType.class);
        ValueInstantiator valueInstantiator = mock(ValueInstantiator.class);
        KeyDeserializer keyDeser = null;
        JsonDeserializer<Object> valueDeser = null;
        TypeDeserializer valueTypeDeser = mock(TypeDeserializer.class); // This is NOT null

        MapDeserializer deserializer = new MapDeserializer(mapType, valueInstantiator, keyDeser, valueDeser, valueTypeDeser);

        // Act & Assert
        assertFalse("Should not be cachable when valueTypeDeserializer is present", 
            deserializer.isCachable());
    }

    @Test
    public void testIsCachable_IgnorablePropertiesNotNull_ReturnsFalse() {
        // Arrange: _valueTypeDeserializer is null, but _ignorableProperties is NOT null
        JavaType mapType = mock(JavaType.class);
        ValueInstantiator valueInstantiator = mock(ValueInstantiator.class);
        KeyDeserializer keyDeser = null;
        JsonDeserializer<Object> valueDeser = null;
        TypeDeserializer valueTypeDeser = null;

        // Using the protected constructor to inject ignorable properties
        HashSet<String> ignorable = new HashSet<>();
        ignorable.add("someProperty");

        MapDeserializer deserializer = new MapDeserializer(mapType, valueInstantiator, keyDeser, valueDeser, valueTypeDeser, ignorable);

        // Act & Assert
        assertFalse("Should not be cachable when ignorable properties are present", 
            deserializer.isCachable());
    }

    @Test
    public void testIsCachable_BothNotNull_ReturnsFalse() {
        // Arrange: Both are NOT null
        JavaType mapType = mock(JavaType.class);
        ValueInstantiator valueInstantiator = mock(ValueInstantiator.class);
        KeyDeserializer keyDeser = null;
        JsonDeserializer<Object> valueDeser = null;
        TypeDeserializer valueTypeDeser = mock(TypeDeserializer.class);

        HashSet<String> ignorable = new HashSet<>();
        ignorable.add("someProperty");

        MapDeserializer deserializer = new MapDeserializer(mapType, valueInstantiator, keyDeser, valueDeser, valueTypeDeser, ignorable);

        // Act & Assert
        assertFalse("Should not be cachable when both are present", 
            deserializer.isCachable());
    }
}
